/* ---- mmpx (third_party/mgba-shaders/mmpx) */
static const char mmpx_fs[] =
	"// Copyright 2020 Morgan McGuire & Mara Gagiu, \n"
	"// provided under the Open Source MIT license https://opensource.org/licenses/MIT\n"
	"\n"
	"varying vec2 texCoord;\n"
	"uniform sampler2D tex;\n"
	"uniform vec2 texSize;\n"
	"\n"
	"float luma(vec4 C) {\n"
	"    return (C.r + C.g + C.b + 1.) * (1. - C.a);\n"
	"}\n"
	"\n"
	"bool all_eq2(vec4 B, vec4 A0, vec4 A1) {\n"
	"    return all(bvec2(B == A0, B == A1));\n"
	"}\n"
	"\n"
	"bool all_eq3(vec4 B, vec4 A0, vec4 A1, vec4 A2) {\n"
	"    return all(bvec3(B == A0, B == A1, B == A2));\n"
	"}\n"
	"\n"
	"bool all_eq4(vec4 B, vec4 A0, vec4 A1, vec4 A2, vec4 A3) {\n"
	"    return all(bvec4(B == A0, B == A1, B == A2, B == A3));\n"
	"}\n"
	"\n"
	"bool any_eq2(vec4 B, vec4 A0, vec4 A1) {\n"
	"    return any(bvec2(B == A0, B == A1));\n"
	"}\n"
	"\n"
	"bool any_eq3(vec4 B, vec4 A0, vec4 A1, vec4 A2) {\n"
	"    return any(bvec3(B == A0, B == A1, B == A2));\n"
	"}\n"
	"\n"
	"bool any_eq4(vec4 B, vec4 A0, vec4 A1, vec4 A2, vec4 A3) {\n"
	"    return any(bvec4(B == A0, B == A1, B == A2, B == A3));\n"
	"}\n"
	"\n"
	"vec4 src(vec2 offset) {\n"
	"    vec2 coord = texCoord + offset / texSize;\n"
	"    return texture2D(tex, coord);\n"
	"}\n"
	"\n"
	"void main() {\n"
	"    vec4 A = src(vec2(-1., -1.));\n"
	"    vec4 B = src(vec2( 0., -1.));\n"
	"    vec4 C = src(vec2(+1., -1.));\n"
	"\n"
	"    vec4 D = src(vec2(-1.,  0.));\n"
	"    vec4 E = src(vec2( 0.,  0.));\n"
	"    vec4 F = src(vec2(+1.,  0.));\n"
	"\n"
	"    vec4 G = src(vec2(-1., +1.));\n"
	"    vec4 H = src(vec2( 0., +1.));\n"
	"    vec4 I = src(vec2(+1., +1.));\n"
	"\n"
	"    vec4 J = E;\n"
	"    vec4 K = E;\n"
	"    vec4 L = E;\n"
	"    vec4 M = E;\n"
	"\n"
	"    bvec3 top = bvec3(A == E, B == E, C == E);\n"
	"    bvec3 mid = bvec3(D == E, true,   F == E);\n"
	"    bvec3 bot = bvec3(G == E, H == E, I == E);\n"
	"\n"
	"    if (!all(top) || !all(mid) || !all(bot)) {\n"
	"        vec4 P = src(vec2(0.  -2.));\n"
	"        vec4 S = src(vec2(0.  +2.));\n"
	"        vec4 Q = src(vec2(-2., 0.));\n"
	"        vec4 R = src(vec2(+2., 0.));\n"
	"        float Bl = luma(B);\n"
	"        float Dl = luma(D);\n"
	"        float El = luma(E);\n"
	"        float Fl = luma(F);\n"
	"        float Hl = luma(H);\n"
	"\n"
	"        //     P\n"
	"        //   A B C\n"
	"        // Q D E F R\n"
	"        //   G H I\n"
	"        //     R\n"
	"\n"
	"        // 1:1 slope rules\n"
	"        if (\n"
	"            (D == B && D != H && D != F) &&\n"
	"            (El >= Dl || E == A) &&\n"
	"            any_eq3(E, A, C, G) &&\n"
	"            ((El < Dl) || A != D || E != P || E != Q)\n"
	"        ) J = D;\n"
	"        if (\n"
	"            (B == F && B != D && B != H) &&\n"
	"            (El >= Bl || E == C) &&\n"
	"            any_eq3(E, A, C, I) &&\n"
	"            ((El < Bl) || C != B || E != P || E != R)\n"
	"        ) K = B;\n"
	"        if (\n"
	"            (H == D && H != F && H != B) &&\n"
	"            (El >= Hl || E == G) &&\n"
	"            any_eq3(E, A, G, I) &&\n"
	"            ((El < Hl) || G != H || E != S || E != Q)\n"
	"        ) L = H;\n"
	"        if (\n"
	"            (F == H && F != B && F != D) &&\n"
	"            (El >= Fl || E == I) &&\n"
	"            any_eq3(E, C, G, I) &&\n"
	"            ((El < Fl) || I != H || E != R || E != S)\n"
	"        ) M = F;\n"
	"\n"
	"        // Intersection rules\n"
	"        if (\n"
	"            E != F &&\n"
	"            all_eq4(E, C, I, D, Q) &&\n"
	"            all_eq2(F, B, H) &&\n"
	"            F != src(vec2(+3.,  0.))\n"
	"        ) K = M = F;\n"
	"        if (\n"
	"            E != D &&\n"
	"            all_eq4(E, A, G, F, R) &&\n"
	"            all_eq2(D, B, H) &&\n"
	"            D != src(vec2(-3.,  0.))\n"
	"        ) J = L = D;\n"
	"        if (\n"
	"            E != H &&\n"
	"            all_eq4(E, G, I, B, P) &&\n"
	"            all_eq2(H, D, F) &&\n"
	"            H != src(vec2( 0., +3.))\n"
	"        ) L = M = H;\n"
	"        if (\n"
	"            E != B &&\n"
	"            all_eq4(E, A, C, H, S) &&\n"
	"            all_eq2(B, D, F) &&\n"
	"            B != src(vec2( 0., -3.))\n"
	"        ) J = K = B;\n"
	"\n"
	"        if (\n"
	"            Bl < El &&\n"
	"            all_eq4(E, G, H, I, S) &&\n"
	"            !any_eq4(E, A, D, C, F)\n"
	"        ) J = K = B;\n"
	"        if (\n"
	"            Hl < El &&\n"
	"            all_eq4(E, A, B, C, P) &&\n"
	"            !any_eq4(E, D, G, I, F)\n"
	"        ) L = M = H;\n"
	"        if (\n"
	"            Fl < El &&\n"
	"            all_eq4(E, A, D, G, Q) &&\n"
	"            !any_eq4(E, B, C, I, H)\n"
	"        ) K = M = F;\n"
	"        if (\n"
	"            Dl < El &&\n"
	"            all_eq4(E, C, F, I, R) &&\n"
	"            !any_eq4(E, B, A, G, H)\n"
	"        ) J = L = D;\n"
	"\n"
	"        // 2:1 slope rules\n"
	"        if (H != B) { \n"
	"            if (H != A && H != E && H != C) {\n"
	"                if (all_eq3(H, G, F, R) && !any_eq2(H, D, src(vec2(+2., -1.)))) L = M;\n"
	"                if (all_eq3(H, I, D, Q) && !any_eq2(H, F, src(vec2(-2., -1.)))) M = L;\n"
	"            }\n"
	"            \n"
	"            if (B != I && B != G && B != E) {\n"
	"                if (all_eq3(B, A, F, R) && !any_eq2(B, D, src(vec2(+2., +1.)))) J = K;\n"
	"                if (all_eq3(B, C, D, Q) && !any_eq2(B, F, src(vec2(-2., +1.)))) K = J;\n"
	"            }\n"
	"        } // H !== B\n"
	"        \n"
	"        if (F != D) { \n"
	"            if (D != I && D != E && D != C) {\n"
	"                if (all_eq3(D, A, H, S) && !any_eq2(D, B, src(vec2(+1., +2.)))) J = L;\n"
	"                if (all_eq3(D, G, B, P) && !any_eq2(D, H, src(vec2(+1., -2.)))) L = J;\n"
	"            }\n"
	"            \n"
	"            if (F != E && F != A && F != G) {    \n"
	"                if (all_eq3(F, C, H, S) && !any_eq2(F, B, src(vec2(-1., +2.)))) K = M;\n"
	"                if (all_eq3(F, I, B, P) && !any_eq2(F, H, src(vec2(-1., -2.)))) M = K;\n"
	"            }\n"
	"        } // F !== D\n"
	"    } // not constant\n"
	"\n"
	"    if (fract((texCoord * texSize).x) < 0.5) {\n"
	"        if (fract((texCoord * texSize).y) < 0.5) {\n"
	"            gl_FragColor = J;\n"
	"        } else {\n"
	"            gl_FragColor = L;\n"
	"        }\n"
	"    } else {\n"
	"        if (fract((texCoord * texSize).y) < 0.5) {\n"
	"            gl_FragColor = K;\n"
	"        } else {\n"
	"            gl_FragColor = M;\n"
	"        }\n"
	"    }\n"
	"}\n"
	"\n";

